.feedback-form-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: flex;

  justify-content: right;

  align-items: center;
  z-index: 1000;
}

.feedback-form-container {
  background: #fff;
  padding: 20px;
  border-radius: 10px;
  width: 400px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.close-button {
  position: absolute;
  top: 10px;
  right: 10px;
  background: none;
  border: none;
  font-size: 24px;
  color: #333;
  cursor: pointer;
}

.close-button:hover {
  color: #565454;
}

.feedback-form h2 {
  margin-bottom: 20px;
  font-size: 1.5rem;
  text-align: center;
  font-weight: bold;
}

.feedback-form label {
  display: block;
  font-weight: bold;
  margin-bottom: 8px;
  text-align: left;
}

.feedback-form input,
.feedback-form textarea {
  width: 100%;
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 5px;
  box-sizing: border-box;
  margin-bottom: 10px;
}

.feedback-form textarea {
  resize: none;
}

.rating {
  display: flex;
  align-items: left;
  flex-direction: column;
  gap: 10px;
}

.stars {
  display: flex;

  gap: 10px;
  justify-content: left;
  margin-bottom: 10px;
}

.star {
  font-size: 24px;
  color: #ccc;
  cursor: pointer;
}

.star.filled {
  color: #ffc107;
}

.star:hover,
.star.filled:hover ~ .star {
  color: #ffc107;
}

.submit-button {
  width: 100%;
  padding: 10px;
  background: #4caf50;
  color: #fff;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 16px;
  text-align: center;
}

.submit-button:hover {
  background: #45a049;
}

.feedback-success {
  text-align: center;
}

.feedback-success h2 {
  margin-bottom: 20px;
  font-size: 1.5rem;
}

@media (max-width: 768px) {
  .feedback-form-container {
    height: auto;
    width: 65%;
    padding: 20px;
    gap: 10px;
    margin-right: 10%;
  }

  .close-button {
    font-size: 20px;
    top: 5px;
    right: 5px;
  }

  .feedback-form h2 {
    font-size: 1.25rem;
    margin-bottom: 15px;
  }

  .feedback-form input,
  .feedback-form textarea {
    padding: 8px;
    font-size: 14px;
  }

  .star {
    font-size: 20px;
  }

  .submit-button {
    font-size: 14px;
    padding: 8px;
  }
}
