.sidebar {
  width: 250px;
  background-color: #f4f4f4;
  overflow-y: auto;

  position: fixed;
  left: 0;
  margin-top: 100%;
  padding: 0;
}

.sidebar ul {
  list-style-type: none;
  padding: 0;
  margin-top: 15%;
}

.sidebar li {
  padding: 15px;
  margin: 5px 0;
  color: #000;
  cursor: pointer;
  background-color: white;
  border-radius: 6px 0 0 6px;
  transition: background-color 0.3s;
}

.sidebar li:hover {
  background-color: #ddd;
}

.sidebar .icon {
  font-size: 20px;
  margin-right: 15px;
  color: #555;
}

.sidebar .menu-text {
  font-size: 16px;
  color: #333;
}

.view-profile {
  padding: 1%;
  cursor: pointer;
  margin-top: 10%;
  text-align: center;
}

.view-profile-text {
  color: #007bff;
  cursor: pointer;
  transition: color 0.3s;
}

.view-profile-text:hover {
  color: #0056b3;
}

.sidebar li.active {
  background: #ddd;
  color: #333;
  font-weight: bold;
}

.bottom-nav {
  display: none;
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: white;
  box-shadow: 0 -2px 5px rgba(0, 0, 0, 0.1);
  display: flex;
  justify-content: space-around;
  padding: 10px 0;
  z-index: 1000;
}

.sidebar {
  width: 250px;
  background: #000;
  color: #fff;
  position: fixed;
  left: 0;
  top: 0;
  bottom: 0;
  overflow-y: auto;
  padding-top: 1rem;
}

.mobile-menu-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 1000;
  display: flex;
  justify-content: flex-start;
}

.mobile-menu {
  background: #fff;
  color: #000;
  width: 300px;
  max-width: 90%;
  height: 100%;
  overflow-y: auto;
  padding: 1.5rem;
  box-shadow: 8px 0 30px rgba(0, 0, 0, 0.3);
}

.mobile-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid #e5e7eb;
}
.mobile-title {
  font-size: 1.25rem;
  font-weight: 600;
  color: #111;
}
.mobile-close {
  background: none;
  border: none;
  color: #6b7280;
  cursor: pointer;
  transition: color 0.2s;
}
.mobile-close:hover {
  color: #000;
}

.mobile-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.mobile-list-item {
  border-bottom: 1px solid #e5e7eb;
}
.mobile-list-item:last-child {
  border-bottom: none;
}

.mobile-item {
  display: flex;
  align-items: center;
  padding: 1rem 1.25rem;
  cursor: pointer;
  border-radius: 0.5rem;
  transition: background 0.2s;
}
.mobile-item:hover {
  background: #f3f4f6;
}
.mobile-item.active {
  background: #001d4a;
  color: #fff;
}
.mobile-icon {
  margin-right: 1rem;
  color: #6b7280;
}
.mobile-item.active .mobile-icon {
  color: #fff;
}
.mobile-label {
  flex: 1;
  font-size: 1rem;
  font-weight: 500;
}
.mobile-arrow {
  color: #6b7280;
}
.mobile-item.active .mobile-arrow {
  color: #fff;
}

.mobile-submenu {
  list-style: none;
  margin: 0.5rem 0 0 3rem;
  padding: 0;
}
.mobile-submenu-item {
  padding: 0.75rem 1rem;
  border-radius: 0.375rem;
  cursor: pointer;
  font-size: 0.9375rem;
  transition: background 0.2s;
}
.mobile-submenu-item:hover {
  background: #e5e7eb;
}
.mobile-submenu-item.active {
  color: #0f0b0b;
}

.mobile-no-items {
  text-align: center;
  padding: 2rem 0;
  color: #6b7280;
}

.desktop-submenu {
  margin-left: 2rem;
  margin-top: 0.5rem;
}

.desktop-submenu-item {
  display: flex;
  align-items: center;
  padding: 1rem 1.25rem;
  color: #fff;
  background: #111;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.2s;
  margin-bottom: 0.25rem;
  font-size: 1rem;
  font-weight: 500;
}

.desktop-submenu-item:hover {
  background: #333;
}

.desktop-submenu-item.active {
  background: #000;
  color: #fff;
  font-weight: 600;
}

.desktop-submenu-item .icon {
  color: #9ca3af;
  margin-right: 0.75rem;
}

.desktop-submenu-item.active {
  background: #9e9d9d;
  color: #161414;
  font-weight: 600;
}

.bottom-nav {
  background: #fff;
  box-shadow: 0 -2px 8px rgba(0, 0, 0, 0.1);
}
.bottom-nav button {
  color: #000000;
  transition: color 0.2s, transform 0.15s;
}
.bottom-nav button:hover {
  color: #000;
}
.bottom-nav button:active,
.bottom-nav button:focus {
  transform: translateY(-2px);
}
li .bottom-nav button.text-blue-400 {
  color: #2563eb;
}

@media (min-width: 768px) {
  .bottom-nav {
    display: none;
  }
}
@media (max-width: 767px) {
  .sidebar {
    display: none;
  }
}

.bottom-nav {
