@media (min-width: 768px) {
  .bottom-nav {
    display: none;
  }
}

@media screen and (max-width: 768px) {
  .bottom-nav {
    display: flex;
    position: fixed;
  }

  .sidebar {
    display: none;
  }
}

.keyboard-open .bottom-nav {
  transform: translateY(100%);
}
